# ---------------- evaluator ----------------
RK = [5 ** (c >> 2) for c in range(52)]
SV = [1 << (3 * (c & 3)) for c in range(52)]
RB = [1 << (c >> 2) for c in range(52)]

def _straight_high(mask):
    for hi in range(12, 3, -1):
        need = 0x1F << (hi - 4)
        if mask & need == need:
            return hi
    if mask & 0x100F == 0x100F:
        return 3
    return -1

def _top(mask, n):
    out = []
    for r in range(12, -1, -1):
        if mask >> r & 1:
            out.append(r)
            if len(out) == n: break
    return out

def _pack(cat, ks):
    v = cat
    for i in range(5):
        v = v * 16 + (ks[i] if i < len(ks) else 0)
    return v

FL = [0] * 8192
for _m in range(8192):
    if bin(_m).count('1') >= 5:
        _s = _straight_high(_m)
        FL[_m] = _pack(8, [_s]) if _s >= 0 else _pack(5, _top(_m, 5))

def _val_counts(cnt):
    mask = 0
    for r in range(13):
        if cnt[r]: mask |= 1 << r
    quads = [r for r in range(12, -1, -1) if cnt[r] == 4]
    trips = [r for r in range(12, -1, -1) if cnt[r] == 3]
    pairs = [r for r in range(12, -1, -1) if cnt[r] == 2]
    if quads:
        q = quads[0]
        return _pack(7, [q] + _top(mask & ~(1 << q), 1))
    if trips and (len(trips) > 1 or pairs):
        t = trips[0]
        p = max(([trips[1]] if len(trips) > 1 else []) + pairs[:1])
        return _pack(6, [t, p])
    s = _straight_high(mask)
    if s >= 0:
        return _pack(4, [s])
    if trips:
        t = trips[0]
        return _pack(3, [t] + _top(mask & ~(1 << t), 2))
    if len(pairs) >= 2:
        a, b = pairs[0], pairs[1]
        return _pack(2, [a, b] + _top(mask & ~(1 << a) & ~(1 << b), 1))
    if pairs:
        a = pairs[0]
        return _pack(1, [a] + _top(mask & ~(1 << a), 3))
    return _pack(0, _top(mask, 5))

RT = {}
for _n in (5, 6, 7):
    for _combo in itertools.combinations_with_replacement(range(13), _n):
        _cnt = [0] * 13
        for _r in _combo: _cnt[_r] += 1
        if max(_cnt) > 4: continue
        RT[sum(5 ** _r for _r in _combo)] = _val_counts(_cnt)

FS = [-1] * 4096
for _a in range(8):
    for _b in range(8):
        for _c in range(8):
            for _d in range(8):
                if _a + _b + _c + _d <= 7:
                    FS[_a | _b << 3 | _c << 6 | _d << 9] = 0 if _a >= 5 else 1 if _b >= 5 else 2 if _c >= 5 else 3 if _d >= 5 else -1

def ev(cards):
    k = 0; s = 0
    for c in cards:
        k += RK[c]; s += SV[c]
    f = FS[s]
    if f >= 0:
        m = 0
        for c in cards:
            if c & 3 == f: m |= RB[c]
        return FL[m]
    return RT[k]

