# ---------------- preflop tables ----------------
def cls_of(c1, c2):
    a, b = c1 >> 2, c2 >> 2
    hi, lo = (a, b) if a >= b else (b, a)
    if hi == lo: return hi * 13 + hi
    if (c1 & 3) == (c2 & 3): return hi * 13 + lo
    return lo * 13 + hi

def _ncombo(i):
    a, b = divmod(i, 13); return 6 if a == b else (4 if a > b else 12)

PCT = [0.0] * 169
COMBOS = []
_cum = 0
for _i in ORDER:
    _a, _b = divmod(_i, 13)
    if _a == _b:
        _cs = [(_a*4+s, _a*4+t) for s in range(4) for t in range(s+1, 4)]
    elif _a > _b:
        _cs = [(_a*4+s, _b*4+s) for s in range(4)]
    else:
        _cs = [(_b*4+s, _a*4+t) for s in range(4) for t in range(4) if s != t]
    COMBOS.extend(_cs)
    PCT[_i] = (_cum + len(_cs) * 0.5) / 1326.0
    _cum += len(_cs)
NCOMBO = len(COMBOS)
BUCK = [0.03, 0.05, 0.08, 0.12, 0.17, 0.25, 0.35, 0.5, 0.7, 1.0]

def eq_vs_range(cls, w):
    row = EQR[cls]
    if w <= BUCK[0]: return row[0]
    for j in range(1, 10):
        if w <= BUCK[j]:
            f = (w - BUCK[j-1]) / (BUCK[j] - BUCK[j-1])
            return row[j-1] + f * (row[j] - row[j-1])
    return row[9]

PAY = [10, 7, 5, 4, 3, 2, 1, 0]
_EDGE = [0.0]

def icm(stks, i):
    """Approx Harville ICM over PAY for player i; stks: chip totals (0 = busted this hand)."""
    alive = [k for k in range(len(stks)) if stks[k] > 0]
    n = len(alive)
    if stks[i] <= 0:
        # busted: place = number alive + 1 (bust order ties ignored)
        return PAY[min(7, n)]
    if n == 1: return PAY[0]
    E = _EDGE[0]
    T = float(sum(stks[k] for k in alive)); si = stks[i]
    if n == 2:
        return PAY[1] + (PAY[0] - PAY[1]) * si / T + E
    pn = PAY[n - 1]
    ahead = 0.0; p2 = 0.0
    for k in alive:
        if k == i: continue
        sk = stks[k]
        ahead += si / (si + sk)
        p2 += (sk / T) * si / (T - sk)
    # PAY decomposition: linear slope-1 part + extra 3 for 1st, 1 for 2nd (for n>=3)
    return pn + ahead + 3.0 * si / T + 1.0 * p2 + E


